// §16.1 (Q274): generatable types and GenDesc construction / JS literal emission.
import type { ElemKind, GenDesc } from "../../runtime-js/src/index.ts";
import { elemDesc, layout } from "./layout.ts";
import { isCopy, nonNull, type Type } from "./types.ts";

const vecElemOk = (t: Type): boolean => isGeneratable(t) && isCopy(t) && layout(t) !== undefined;

/** §16.1: whether values of `t` can be generated by `forAll` (and witness search). */
export function isGeneratable(t: Type): boolean {
  switch (t.k) {
    case "num": case "lit": return true;
    case "prim": return t.name === "boolean" || t.name === "string" || t.name === "null";
    case "record": return t.fields.every((f) => isGeneratable(f.type));
    case "union": return t.members.every(isGeneratable);
    case "gen":
      switch (t.name) {
        case "Array": case "ReadonlyArray": case "Set": return isGeneratable(t.args[0]!);
        case "Map": return isGeneratable(t.args[0]!) && isGeneratable(t.args[1]!);
        case "Vec": return vecElemOk(t.args[0]!);
        case "Ref": case "Mut": {
          const inner = t.args[0]!;
          if (inner.k === "record" && inner.struct) return isGeneratable(inner);
          if (inner.k === "gen" && (inner.name === "Vec" || inner.name === "Slice")) return vecElemOk(inner.args[0]!);
          return false;
        }
        default: return false;
      }
    default: return false;
  }
}

/** Builds the runtime `GenDesc` for a generatable type `t`. */
export function genDescOf(t: Type): GenDesc {
  switch (t.k) {
    case "num": return { k: "num", t: t.name };
    case "prim":
      if (t.name === "boolean") return { k: "bool" };
      if (t.name === "string") return { k: "str" };
      if (t.name === "null") return { k: "null" };
      break;
    case "lit": return { k: "lit", v: [t.value] };
    case "record": return { k: "rec", f: t.fields.map((f) => ({ n: f.name, d: genDescOf(f.type) })) };
    case "union": {
      if (t.members.every((m) => m.k === "lit")) return { k: "lit", v: t.members.map((m) => (m as { value: string }).value) };
      const nn = nonNull(t);
      if (nn) return { k: "opt", of: genDescOf(nn) };
      return { k: "union", m: t.members.map(genDescOf) };
    }
    case "gen":
      switch (t.name) {
        case "Array": case "ReadonlyArray": return { k: "arr", of: genDescOf(t.args[0]!) };
        case "Set": return { k: "set", of: genDescOf(t.args[0]!) };
        case "Map": return { k: "map", key: genDescOf(t.args[0]!), val: genDescOf(t.args[1]!) };
        case "Vec": return { k: "vec", of: genDescOf(t.args[0]!), elem: elemDesc(t.args[0]!) as ElemKind };
        case "Ref": case "Mut": {
          const inner = t.args[0]!;
          if (inner.k === "gen" && inner.name === "Slice") return { k: "vec", of: genDescOf(inner.args[0]!), elem: elemDesc(inner.args[0]!) as ElemKind };
          if ((inner.k === "record" && inner.struct) || (inner.k === "gen" && inner.name === "Vec")) return genDescOf(inner);
        }
      }
  }
  throw new Error(`gendesc: type '${t.k}' is not generatable`);
}

/** Emits a `GenDesc` as a JS literal expression. */
export const emitGenDesc = (d: GenDesc): string => JSON.stringify(d);
